<?php require __DIR__.'/../lib/bootstrap.php';require_admin();$pageTitle='Lista VIP';$eventId=(int)($_GET['event']??0);$q=trim($_GET['q']??'');$events=db()->query("SELECT id,title,event_date,vip_capacity FROM events ORDER BY datetime(event_date) DESC")->fetchAll();$sql='SELECT v.*,e.title event_title,e.event_date FROM vip_entries v JOIN events e ON e.id=v.event_id WHERE v.status!="removed"';$args=[];if($eventId){$sql.=' AND v.event_id=?';$args[]=$eventId;}if($q!==''){$sql.=' AND (v.name LIKE ? OR v.email LIKE ? OR v.document LIKE ? OR v.phone LIKE ?)';for($i=0;$i<4;$i++)$args[]='%'.$q.'%';}$sql.=' ORDER BY datetime(e.event_date) DESC,v.name';$st=db()->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$used=$eventId?vip_people_count($eventId):null;$selectedEvent=$eventId?event_by_id($eventId):null;require '_header.php';?>
<?php if($selectedEvent && (int)$selectedEvent['vip_capacity']>0):?><div class="metric-grid compact-metrics"><div class="metric"><span>Pessoas na VIP</span><strong><?=$used?></strong></div><div class="metric"><span>Capacidade</span><strong><?=intval($selectedEvent['vip_capacity'])?></strong></div><div class="metric"><span>Restantes</span><strong><?=max(0,(int)$selectedEvent['vip_capacity']-$used)?></strong></div></div><?php endif;?>
<div class="admin-card"><div class="card-head"><div><h2>Nomes por evento</h2><p>Inclusão, acompanhantes, entrada e exportação.</p></div><div class="action-row"><a class="btn btn-secondary btn-small" href="vip-import.php<?=($eventId?'?event='.$eventId:'')?>">Importar CSV</a><a class="btn btn-secondary btn-small" href="export.php?type=vip<?=($eventId?'&event='.$eventId:'')?>">Exportar CSV</a><a class="btn btn-primary btn-small" href="vip-form.php<?=($eventId?'?event='.$eventId:'')?>">+ Adicionar nome</a></div></div><form class="filters" method="get"><select name="event"><option value="0">Todos os eventos</option><?php foreach($events as $ev):?><option value="<?=intval($ev['id'])?>" <?=$eventId===(int)$ev['id']?'selected':''?>><?=e($ev['title'])?> — <?=date_br($ev['event_date'])?></option><?php endforeach;?></select><input name="q" value="<?=e($q)?>" placeholder="Buscar nome, e-mail, CPF ou telefone"><button class="btn btn-small btn-secondary">Filtrar</button></form><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Evento</th><th>Contato</th><th>Acomp.</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6">Nenhum nome encontrado.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><b><?=e($r['name'])?></b><small class="cell-sub"><?=e($r['document'])?></small></td><td><?=e($r['event_title'])?><small class="cell-sub"><?=e(dt_br($r['event_date']))?></small></td><td><?=e($r['email'])?><small class="cell-sub"><?=e($r['phone'])?></small></td><td>+<?=intval($r['companions'])?></td><td><span class="pill <?=e($r['status'])?>"><?=e(status_label($r['status']))?></span></td><td class="actions"><a href="vip-form.php?id=<?=intval($r['id'])?>">Editar</a><?php if($r['status']==='active'):?><form method="post" action="vip-action.php" class="inline-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=intval($r['id'])?>"><input type="hidden" name="action" value="checkin"><button type="submit" class="link-btn">Entrada</button></form><?php elseif($r['status']==='checked_in'):?><form method="post" action="vip-action.php" class="inline-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=intval($r['id'])?>"><input type="hidden" name="action" value="restore"><button type="submit" class="link-btn">Desfazer entrada</button></form><?php endif;?><form method="post" action="vip-action.php" class="inline-form" onsubmit="return confirm('Remover este nome da lista?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=intval($r['id'])?>"><input type="hidden" name="action" value="remove"><button type="submit" class="link-btn danger">Remover</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php require '_footer.php';?>
